}

# ---------------------------------------------------------------------------------------------------------------------
# CLOUD FUNCTION
# ---------------------------------------------------------------------------------------------------------------------

resource "google_cloudfunctions_function" "http_function" {
  name        = var.function_name
  runtime     = var.function_runtime
  handler     = var.function_handler
  entry_point = var.function_entry_point
  region      = var.region

