# Configure the Azure provider
provider "azurerm" {
  features {}
}

# Define variables
variable "location" {
  type        = string
  description = "The location of the resource group"
}

variable "event_hub_namespace_name" {
  type        = string
  description = "The name of the event hub namespace"
}

variable "event_hub_name" {
  type        = string
  description = "The name of the event hub"
}

variable "consumer_group_name" {
  type        = string
  description = "The name of the consumer group"
}

# Create a resource group
resource "azurerm_resource_group" "this" {
  name     = "rg-event-hub"
  location = var.location
}

# Create an event hub namespace
resource "azurerm_eventhub_namespace" "this" {
  name                = var.event_hub_namespace_name
  location            = azurerm_resource_group.this.location
  resource_group_name = azurerm_resource_group.this.name
  sku                 = "Standard"
  capacity            = 1
  kafka_enabled       = false
}

# Create an event hub
resource "azurerm_eventhub" "this" {
  name                = var.event_hub_name
  namespace_name      = azurerm_eventhub_namespace.this.name
  resource_group_name = azurerm_resource_group.this.name
  partition_count     = 2
  message_retention   = 1
}

# Create a consumer group
resource "azurerm_eventhub_consumer_group" "this" {
  name                = var.consumer_group_name
  namespace_name      = azurerm_eventhub_namespace.this.name
  eventhub_name       = azurerm_eventhub.this.name
  resource_group_name = azurerm_resource_group.this.name
  user_metadata       = "Some metadata"
}

variable "name" {
  type        = string
  description = "Name of the Azure Key Vault"
}

variable "location" {
  type        = string
  description = "Location of the Azure Key Vault"
}

variable "resource_group_name" {
  type        = string
  description = "Name of the resource group"
}

variable "tenant_id" {
  type        = string
  description = "Tenant ID of the Azure subscription"
}

variable "object_id" {
  type        = string
  description = "Object ID of the Azure AD application"
}

variable "sku_name" {
  type        = string
  description = "Sku name of the Azure Key Vault"
  default     = "standard"
}

variable "tags" {
  type        = map(string)
  description = "Tags for the Azure Key Vault"
  default     = {}
}

variable "enable_rbac_authorization" {
  type        = bool
  description = "Enable RBAC authorization for the Azure Key Vault"
  default     = true
}

variable "enable_soft_delete" {
  type        = bool
  description = "Enable soft delete for the Azure Key Vault"
  default     = true
}

variable "enable_purge_protection" {
  type        = bool
  description = "Enable purge protection for the Azure Key Vault"
  default     = true
}

data "azurerm_client_config" "current" {}

resource "azurerm_key_vault" "kv" {
  name                = var.name
  location            = var.location
  resource_group_name = var.resource_group_name
  tenant_id           = data.azurerm_client_config.current.tenant_id
  sku_name            = var.sku_name
  soft_delete_enabled = var.enable_soft_delete
  purge_protection_enabled = var.enable_purge_protection

  tags = var.tags
}

resource "azurerm_key_vault_access_policy" "policy" {
  key_vault_id = azurerm_key_vault.kv.id
  tenant_id    = data.azurerm_client_config.current.tenant_id
  object_id    = var.object_id

  key_permissions = [
    "Create",
    "Get",
    "List",
    "Update",
    "Delete",
    "Recover",
    "Backup",
    "Restore"
  ]

  secret_permissions = [
    "Get",
    "List",
    "Set",
    "Delete",
    "Recover",
    "Backup",
    "Restore"
  ]

  certificate_permissions = [
    "Get",
    "List",
    "Create",
    "Update",
    "Delete",
    "Recover",
    "Backup",
