#########################################################################################
# This configuration creates a Dataflow job, staging bucket, and service account in GCP
#########################################################################################

###########################
# VARIABLES
############################

variable "project_id" {}
variable "region" {
  default = "us-central1"
}
variable "bucket_name" {}
variable "service_account_email" {}
variable "dataflow_job_name" {}
variable "dataflow_job_file" {}
variable "dataflow_job_args" {
  type = list(string)
}

############################
# PROVIDERS
############################

provider "google" {
  version = "~> 4.0"
  project = var.project_id
  region  = var.region
}

############################
# RESOURCES
############################

resource "google_storage_bucket" "staging_bucket" {
  name     = var.bucket_name
  location = var.region
  force_destroy = true
}

resource "google_service_account" "dataflow_service_account" {
  account_id   = "dataflow-service-account"
  display_name = "Dataflow Service Account"
}

resource "google_project_iam_member" "dataflow_service_account_role" {
  project = var.project_id
  role    = "roles/dataflow.worker"
  member  = "serviceAccount:${google_service_account.dataflow_service_account.email}"
}

resource "google_dataflow_flex_template_run" "dataflow_job" {
  provider                = google
  project                  = var.project_id
  region                   = var.region
  template_gcs_path        = "gs://${google_storage_bucket.staging_bucket.name}/${var.dataflow_job_file}"
  parameters               = var.dataflow_job_args
  service_account_email    = google_service_account.dataflow_service_account.email
  launch_parameters {
    container_spec_gcs_path = "gs://${google_storage_bucket.staging_bucket.name}/${var.dataflow_job_file}"
  }
}

output "staging_bucket_name" {
  value = google_storage_bucket.staging_bucket.name
}

output "dataflow_job_id" {
  value = google_dataflow_flex_template_run.dataflow_job.id
}

output "dataflow_service_account_email" {
  value = google_service_account.dataflow_service_account.email
}

terraform {
  required_providers {
    azurerm = {
      source  = "hashicorp/azurerm"
      version = "2.41.0"
    }
  }
}

provider "azurerm" {
  features {}
}

resource "azurerm_resource_group" "sqlservergrp" {
  name     = "sqlserver_grp"
  location = "westus2"
}

variable "sqlserver" {
  type = string
}

variable "username" {
  type = string
}

variable "password" {
  type      = string
  sensitive = true
}

variable "sqlserverdb" {
  type = string
}

variable "sqluid" {
  type = string
}

variable "sqlpwd" {
  type      = string
  sensitive = true
}

variable "start_ip_address" {
  type = string
}

variable "end_ip_address" {
  type = string
}

resource "azurerm_sql_server" "sqlserver" {
  name                         = var.sqlserver
  location                     = azurerm_resource_group.sqlservergrp.location
  resource_group_name          = azurerm_resource_group.sqlservergrp.name
  version                      = "12.0"
  administrator_login          = var.username
  administrator_login_password = var.password
}

resource "azurerm_sql_database" "sqldb" {
  name                = var.sqlserverdb
  resource_group_name = azurerm_resource_group.sqlservergrp.name
  location            = azurerm_resource_group.sqlservergrp.location
  server_name         = azurerm_sql_server.sqlserver.name
  edition             = "Standard"
  sku_name            = "S0"
}

resource "azurerm_sql_firewall_rule" "allow_all" {
  name                = "allow_all"
  resource_group_name = azurerm_resource_group.sqlservergrp.name
  server_name         = azurerm_sql_server.sqlserver.name
  start_ip_address    = var.start_ip_address
  end_ip_address      = var.end_ip_address
}

resource "azurerm_sql_active_directory_administrator" "example" {
  server_name         = azurerm_sql_server.sqlserver.name
  resource_group_name = azurerm_resource_group.sqlservergrp.name
  login               = var.sqluid
  tenant_id           = "your_tenant_id"
  object_id           = "your_object_id"
}

output "sqlserver_fqdn" {
  value = azurerm_sql_server.sqlserver.fully_qualified_domain_name
}

output "sqlserver_dsn" {
  value = "Driver={ODBC Driver 17 for SQL Server};Server=${azurerm_sql_server.sqlserver.fully_qualified_domain_name};Database=${var.sqlserverdb};UID=${var.sqluid};PWD=${var.sqlpwd};"
}

# VARIABLES
variable "project_id" {}
variable "region" {
  default = "us-central1"
}
variable "zone" {
  default = "us-central1-a"
}
variable "instance_name" {}
variable "machine_type" {
  default = "f1-micro"
}
variable "image" {
  default = "debian-cloud/debian-9"
}

# PROVIDERS
provider "google" {
  version = "~> 4.0"
  region  = var.region
  project = var.project_id
}

# RESOURCES
resource "google_compute_network" "vpc" {
  name                    = "my-vpc"
  auto_create_subnetworks = false
}

resource "google_compute_subnetwork" "subnet" {
  name          = "my-subnet"
  ip_cidr_range = "10.10.10.0/24"
  network       = google_compute_network.vpc.id
  region        = var.region
}

resource "google_compute_firewall" "allow_http" {
  name    = "allow-http"
  network = google_compute_network.vpc.id

  allow {
    protocol = "tcp"
    ports    = ["80"]
  }

  target_tags = ["http-server"]
}

resource "google_compute_instance" "vm" {
  name         = var.instance_name
  machine_type = var.machine_type
  zone         = var.zone

  boot_disk {
    initialize_params {
      image = var.image
    }
  }

  network_interface {
    subnetwork = google_compute_subnetwork.subnet.id
    access_config {
    }
  }

  tags = ["http-server"]
}

# Variables
variable "name" {
  type        = string
  description = "The name of the service"
}

variable "cpu" {
  type        = number
  description = "The amount of CPU to allocate to the task"
}

variable "memory" {
  type        = number
  description = "The amount of memory to allocate to the task"
}

variable "load_balancer" {
  type        = string
  description = "The ARN of the load balancer"
}

variable "hostname" {
  type        = string
  description = "The hostname of the service"
}

variable "network" {
  type        = string
  description = "The ID of the network"
}

variable "aws_region" {
  type        = string
  description = "The AWS region"
}

variable "sys_name" {
  type        = string
  description = "The system name"
}

variable "app_ctr_img_tag" {
  type        = string
  description = "The tag of the app container image"
}

variable "api_ctr_img_tag" {
  type        = string
  description = "The tag of the API container image"
}

# CloudWatch Resources
resource "aws_cloudwatch_log_group" "app_task_loggrp" {
  name = "/ecs/${var.sys_name}-app-task"
}

resource "aws_cloudwatch_log_group" "api_task_loggrp" {
  name = "/ecs/${var.sys_name}-api-task"
}

# ECS Resources
resource "aws_ecs_cluster" "app_ctr_cluster" {
  name = "${var.sys_name}-app-ctr-cluster"
}

resource "aws_ecs_cluster" "api_ctr_cluster" {
  name = "${var.sys_name}-api-ctr-cluster"
}

# IAM Resources
data "aws_iam_policy_document" "ecs_task_assume_role_policy" {
  statement {
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ecs-tasks.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "app_ecsTaskExecutionRole" {
  name               = "${var.sys_name}-app-ecsTaskExecutionRole"
  assume_role_policy = data.aws_iam_policy_document.ecs_task_assume_role_policy.json
}

resource "aws_iam_role_policy_attachment" "app_ecsTaskExecutionRole_policy" {
  role       = aws_iam_role.app_ecsTaskExecutionRole.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonECSTaskExecutionRolePolicy"
}

resource "aws_iam_role" "api_ecsTaskExecutionRole" {
  name               = "${var.sys_name}-api-ecsTaskExecutionRole"
  assume_role_policy = data.aws_iam_policy_document.ecs_task_assume_role_policy.json
}

resource "aws_iam_role_policy_attachment" "api_ecsTaskExecutionRole_policy" {
  role       = aws_iam_role.api_ecsTaskExecutionRole.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonECSTaskExecutionRolePolicy"
}

# ECR Resources
resource "aws_ecr_repository" "app_ctr_img_repo" {
  name = "${var.sys_name}-app-ctr-img-repo"
}

resource "aws_ecr_repository" "api_ctr_img_repo" {
  name = "${var.sys_name}-api-ctr-img-repo"
}

data "aws_ecr_image" "app_image" {
  repository_name = aws_ecr_repository.app_ctr_img_repo.name
  image_tag       = var.app_ctr_img_tag
}

data "aws_ecr_image" "api_image" {
  repository_name = aws_ecr_repository.api_ctr_img_repo.name
  image_tag       = var.api_ctr_img_tag
}

# Task Definitions
resource "aws_ecs_task_definition" "app_taskdef" {
  family                   = "${var.sys_name}-app-taskdef"
  container_definitions    = jsonencode([
    {
      name        = "${var.sys_name}-app-task",
      image       = "${aws_ecr_repository.app_ctr_img_repo.repository_url}@${data.aws_ecr_image.app_image.image_digest}",
      essential   = true,
      portMappings = [
        {
          containerPort = 3000,
          hostPort      = 3000
        }
      ],
      memory = 512,
      cpu    = 256,
      logConfiguration = {
        logDriver = "awslogs",
        options = {
          awslogs-group         = aws_cloudwatch_log_group.app_task_loggrp.name,
          awslogs-region        = var.aws_region,
          awslogs-stream-prefix = "ecs"
        }
      }
    }
  ])
  requires_compatibilities = ["FARGATE"]
  network_mode             = "awsvpc"
  cpu                      = var.cpu
  memory                   = var.memory
  execution_role_arn       = aws_iam_role.app_ecsTaskExecutionRole.arn
}

resource "aws_ecs_task_definition" "api_taskdef" {
  family                   = "${var.sys_name}-api-taskdef"
  container_definitions    = jsonencode([
    {
      name        = "${var.sys_name}-api-task",
      image       = "${aws_ecr_repository.api_ctr_img_repo.repository_url}@${data.aws_ecr_image.api_image.image_digest}",
      essential   = true,
      portMappings = [
        {
          containerPort = 3000,
          hostPort      = 3000
        }
      ],
      memory = 512,
      cpu    = 256,
      logConfiguration = {
        logDriver = "awslogs",
        options = {
          awslogs-group         = aws_cloudwatch_log_group.api_task_loggrp.name,
          awslogs-region        = var.aws_region,
          awslogs-stream-prefix = "ecs"
        }
      }
    }
  ])
  requires_compatibilities = ["FARGATE"]
  network_mode             = "awsvpc"
  cpu                      = var.cpu
  memory                   = var.memory
  execution_role_arn       = aws_iam_role.api_ecsTaskExecutionRole.arn
}

# Services
resource "aws_ecs_service" "app_service" {
  name            = "${var.sys_name}-app-service"
  cluster         = aws_ecs_cluster.app_ctr_cluster.name
  task_definition = aws_ecs_task_definition.app_taskdef.arn
  desired_count   = 1
  launch_type      = "FARGATE"

  network_configuration {
    security_groups  = [aws_security_group.app_sg.id]
    subnets          = [aws_subnet.app_subnet.id]
    assign_public_ip = "ENABLED"
  }

  load_balancer {
    target_group_arn = aws_alb_target_group.app_tg.arn
    container_name   = "${var.sys_name}-app-task"
    container_port   = 3000
  }

  depends_on = [aws_alb_listener.app_listener]
}

resource "aws_ecs_service" "api_service" {
  name            = "${var.sys_name}-api-service"
  cluster         = aws_ecs_cluster.api_ctr_cluster.name
  task_definition = aws_ecs_task_definition.api_taskdef.arn
  desired_count   = 1
  launch_type      = "FARGATE"

  network_configuration {
    security_groups  = [aws_security_group.api_sg.id]
    subnets          = [aws_subnet.api_subnet.id]
    assign_public_ip = "ENABLED"
  }

  load_balancer {
    target_group_arn = aws_alb_target_group.api_tg.arn
    container_name   = "${var.sys_name}-api-task"
    container_port   = 3000
  }

  depends_on = [aws_alb_listener.api_listener]
}

# ALB Resources
resource "aws_alb" "app_alb" {
  name            = "${var.sys_name}-app-alb"
  subnets         = [aws_subnet.app_subnet.id]
  security_groups = [aws_security_group.app_sg.id]
}

resource "aws_alb" "api_alb" {
  name            = "${var.sys_name}-api-alb"
  subnets         = [aws_subnet.api_subnet.id]
  security_groups = [aws_security_group.api_sg.id]
}

resource "aws_alb_target_group" "app_tg" {
  name     = "${var.sys_name}-app-tg"
  port     = 3000
  protocol = "HTTP"
  vpc_id   = aws_vpc.app_vpc.id
}

resource "aws_alb_target_group" "api_tg" {
  name     = "${var.sys_name}-api-tg"
  port     = 3000
  protocol = "HTTP"
  vpc_id   = aws_vpc.api_vpc.id
}

resource "aws_alb_listener" "app_listener" {
  load_balancer_arn = aws_alb.app_alb.arn
  port              = "80"
  protocol          = "HTTP"

  default_action {
    target_group_arn = aws_alb_target_group.app_tg.arn
    type             = "forward"
  }
}

resource "aws_alb_listener" "api_listener" {
  load_balancer_arn = aws_alb.api_alb.arn
  port              = "80"
  protocol          = "HTTP"

  default_action {
    target_group_arn = aws_alb_target_group.api_tg.arn
    type             = "forward"
  }
}

# VPC Resources
resource "aws_vpc" "app_vpc" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_vpc" "api_vpc" {
  cidr_block = "10.1.0.0/16"
}

resource

provider "aws" {
  region = var.region
}

provider "kubernetes" {
  host                   = module.eks.cluster_endpoint
  cluster_ca_certificate = base64decode(module.eks.cluster_certificate_authority_data)

  exec {
    api_version = "client.authentication.k8s.io/v1beta1"
    command     = "aws"
    args = [
      "eks",
      "get-token",
      "--cluster-name",
      module.eks.cluster_id,
    ]
  }
}

locals {
  name            = "ex-${replace(basename(path.cwd), "_", "-")}"
  cluster_version = "1.22"
  region          = var.region

  tags = {
    Example    = local.name
    GithubRepo = "terraform-aws-eks"
    GithubOrg  = "terraform-aws-modules"
  }
}

variable "region" {
  type        = string
  description = "AWS Region"
}

variable "vpc_cidr" {
  type        = string
  description = "VPC CIDR"
}

variable "availability_zones" {
  type        = list(string)
  description = "Availability Zones"
}

variable "instance_type" {
  type        = string
  description = "Instance Type"
}

variable "node_group_name" {
  type        = string
  description = "Node Group Name"
}

variable "node_group_instance_type" {
  type        = string
  description = "Node Group Instance Type"
}

variable "node_group_desired_capacity" {
  type        = number
  description = "Node Group Desired Capacity"
}

variable "node_group_max_capacity" {
  type        = number
  description = "Node Group Max Capacity"
}

variable "node_group_min_capacity" {
  type        = number
  description = "Node Group Min Capacity"
}

data "aws_caller_identity" "current" {}

module "vpc" {
  source = "terraform-aws-modules/vpc/aws"

  name = local.name
  cidr = var.vpc_cidr

  azs             = var.availability_zones
  public_subnets  = [for az in var.availability_zones : cidrsubnet(var.vpc_cidr, 8, index(var.availability_zones, az))]
  private_subnets = [for az in var.availability_zones : cidrsubnet(var.vpc_cidr, 8, index(var.availability_zones, az) + 10)]

  enable_nat_gateway = true
  enable_vpn_gateway = false

  tags = local.tags
}

module "eks" {
  source = "terraform-aws-modules/eks/aws"

  cluster_name                    = local.name
  cluster_version                 = local.cluster_version
  cluster_endpoint_private_access = true
  cluster_endpoint_public_access  = true

  vpc_id     = module.vpc.vpc_id
  subnet_ids = module.vpc.private_subnets

  cluster_addons = {
    coredns = {
      resolve_conflicts = "OVERWRITE"
    }
    kube-proxy = {}
    vpc-cni = {
      resolve_conflicts = "OVERWRITE"
    }
  }

  cluster_encryption_config = [{
    provider_key_arn = aws_kms_key.eks.arn
    resources        = ["secrets"]
  }]

  # Extend cluster security group rules
  cluster_security_group_additional_rules = {
    egress_nodes_ephemeral_ports_tcp = {
      description                = "To node 1025-65535"
      protocol                   = "tcp"
      from_port                  = 1025
      to_port                    = 65535
      type                       = "egress"
      source_node_security_group = true
    }
  }
}

resource "aws_kms_key" "eks" {
  description             = "EKS KMS Key"
  deletion_window_in_days = 10
}

resource "aws_iam_role" "eks_node" {
  name        = "${local.name}-eks-node"
  description = "EKS Node IAM Role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      },
    ]
  })
}

resource "aws_iam_role_policy_attachment" "eks_node_AmazonEKSWorkerNodePolicy" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSWorkerNodePolicy"
  role       = aws_iam_role.eks_node.name
}

resource "aws_iam_role_policy_attachment" "eks_node_AmazonEC2ContainerRegistryReadOnly" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEC2ContainerRegistryReadOnly"
  role       = aws_iam_role.eks_node.name
}

resource "aws_iam_role_policy_attachment" "eks_node_AmazonEKS_CNI_Policy" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKS_CNI_Policy"
  role       = aws_iam_role.eks_node.name
}

module "eks_node_group" {
  source = "terraform-aws-modules/eks/aws//modules/eks_managed_node_group"

  name                 = var.node_group_name
  cluster_name         = module.eks.cluster_name
  instance_types       = [var.node_group_instance_type]
  node_group_name      = var.node_group_name
  node_role_arn        = aws_iam_role.eks_node.arn
  subnet_ids           = module.vpc.private_subnets
  desired_capacity     = var.node_group_desired_capacity
  max_capacity         = var.node_group_max_capacity
  min_capacity         = var.node_group_min_capacity
  force_update_version = true

  depends_on = [
    aws_iam_role_policy_attachment.eks_node_AmazonEKSWorkerNodePolicy,
    aws_iam_role_policy_attachment.eks_node_AmazonEC2ContainerRegistryReadOnly,
    aws_iam_role_policy_attachment.eks_node_AmazonEKS_CNI_Policy,
  ]
}

