# Create a VPC network in GCP
module "gcp_vpc" {
  source  = "terraform-google-modules/network/google"
  version = "~> 2.5.0"

  project_id   = var.gcp_project
  network_name = "gcp-vpc"

  subnets = [
    {
      subnet_name   = "gcp-subnet1"
      subnet_ip     = "10.2.1.0/24"
      subnet_region = var.gcp_region
    },
    {
      subnet_name   = "gcp-subnet2"
      subnet_ip     = "10.2.2.0/24"
      subnet_region = var.gcp_region
    },
  ]
}

terraform {
  required_version = ">= 0.12.8"
}

# ---------------------------------------------------------------------------------------------------------------------
# VARIABLES
# ---------------------------------------------------------------------------------------------------------------------

variable "project" {
  type        = string
  description = "The ID of the project to deploy the function to"
}

variable "region" {
  type        = string
  default     = "us-central1"
  description = "The region to deploy the function to"
}

variable "function_name" {
  type        = string
  description = "The name of the Cloud Function"
}

variable "function_runtime" {
  type        = string
  default     = "nodejs14"
  description = "The runtime environment of the Cloud Function"
}

variable "function_handler" {
  type        = string
  default     = "index.handler"
  description = "The handler of the Cloud Function"
}

variable "service_account_email" {
  type        = string
  description = "The email of the service account to use for the Cloud Function"
}

# ---------------------------------------------------------------------------------------------------------------------
# PROVIDERS
# ---------------------------------------------------------------------------------------------------------------------

provider "google" {
  version = "~> 3.52.0"
  project = var.project
  region  = var.region
}

# ---------------------------------------------------------------------------------------------------------------------
# SERVICE ACCOUNT
# ---------------------------------------------------------------------------------------------------------------------

resource "google_service_account" "function_service_account" {
  account_id = "function-service-account"
}

# ---------------------------------------------------------------------------------------------------------------------
# CLOUD FUNCTION
# ---------------------------------------------------------------------------------------------------------------------

resource "google_cloudfunctions_function" "function" {
  name        = var.function_name
  runtime     = var.function_runtime
  handler     = var.function_handler
  service_account_email = var.service_account_email
  available_memory_mb   = 128
  timeout_seconds       = 60
  entry_point           = "index.handler"
  https_trigger {
    security_level = "SECURE_ALWAYS"
  }
}

# ---------------------------------------------------------------------------------------------------------------------
# IAM POLICIES
# ---------------------------------------------------------------------------------------------------------------------

resource "google_cloudfunctions_service_account_iam_policy" "policy" {
  service_account_id = google_service_account.function_service_account.id
  policy            = data.google_iam_policy.function_policy.policy_data
}

data "google_iam_policy" "function_policy" {
  binding {
    role = "roles/cloudfunctions.invoker"
    members = [
      "allUsers",
    ]
  }
}

variable "resource_group_name" {
  type        = string
  description = "Name of the resource group"
}

variable "location" {
  type        = string
  description = "Location of the resource group"
}

variable "nsg_name" {
  type        = string
  description = "Name of the network security group"
}

variable "vnet_name" {
  type        = string
  description = "Name of the virtual network"
}

variable "subnet_name" {
  type        = string
  description = "Name of the subnet"
}

variable "subnet_address_prefix" {
  type        = string
  description = "Address prefix of the subnet"
}

provider "azurerm" {
  features {}
}

resource "azurerm_resource_group" "rg" {
  name     = var.resource_group_name
  location = var.location
}

resource "azurerm_virtual_network" "vnet" {
  name                = var.vnet_name
  address_space       = [var.subnet_address_prefix]
  location            = azurerm_resource_group.rg.location
  resource_group_name = azurerm_resource_group.rg.name
}

resource "azurerm_subnet" "subnet" {
  name                 = var.subnet_name
  resource_group_name  = azurerm_resource_group.rg.name
  virtual_network_name = azurerm_virtual_network.vnet.name
  address_prefixes     = [var.subnet_address_prefix]
}

resource "azurerm_network_security_group" "nsg" {
  name                = var.nsg_name
  location            = azurerm_resource_group.rg.location
  resource_group_name = azurerm_resource_group.rg.name
}

resource "azurerm_network_security_rule" "allow_https" {
  name                        = "allow_https"
  priority                    = 100
  direction                   = "Inbound"
  access                      = "Allow"
  protocol                    = "Tcp"
  source_port_range          = "*"
  destination_port_range     = "443"
  source_address_prefix      = "*"
  destination_address_prefix = "*"
  resource_group_name         = azurerm_resource_group.rg.name
  network_security_group_name = azurerm_network_security_group.nsg.name
}

resource "azurerm_network_security_rule" "deny_all_inbound" {
  name                        = "deny_all_inbound"
  priority                    = 200
  direction                   = "Inbound"
  access                      = "Deny"
  protocol                    = "*"
  source_port_range          = "*"
  destination_port_range     = "*"
  source_address_prefix      = "*"
  destination_address_prefix = "*"
  resource_group_name         = azurerm_resource_group.rg.name
  network_security_group_name = azurerm_network_security_group.nsg.name
}

resource "azurerm_subnet_network_security_group_association" "nsg_association" {
  subnet_id                 = azurerm_subnet.subnet.id
  network_security_group_id = azurerm_network_security_group.nsg.id
}

variable "cluster_name" {
  type        = string
  description = "The name of the AKS cluster"
}

variable "location" {
  type        = string
  description = "The location of the AKS cluster"
}

variable "resource_group_name" {
  type        = string
  description = "The name of the resource group"
}

variable "dns_prefix" {
  type        = string
  description = "The DNS prefix of the AKS cluster"
}

variable "kubernetes_version" {
  type        = string
  description = "The version of Kubernetes"
}

variable "private_cluster_enabled" {
  type        = bool
  description = "Whether the cluster is private"
}

variable "agent_count" {
  type        = number
  description = "The number of agents in the default node pool"
}

variable "agent_vm_size" {
  type        = string
  description = "The size of the virtual machines in the default node pool"
}

variable "node_os_disk_size_gb" {
  type        = number
  description = "The size of the OS disk in GB"
}

variable "admin_group_id" {
  type        = string
  description = "The ID of the admin group"
}

resource "azurerm_user_assigned_identity" "kubelet_identity" {
  name                = "${var.cluster_name}-agentpool-identity"
  location            = var.location
  resource_group_name = var.resource_group_name
}

resource "azurerm_kubernetes_cluster" "aks" {
  name                = var.cluster_name
  location            = var.location
  resource_group_name = var.resource_group_name
  dns_prefix          = var.dns_prefix
  kubernetes_version  = var.kubernetes_version
  private_cluster_enabled = var.private_cluster_enabled

  default_node_pool {
    name            = "agentpool"
    node_count      = var.agent_count
    vm_size         = var.agent_vm_size
    os_disk_size_gb = var.node_os_disk_size_gb
    type            = "VirtualMachineScaleSets"
    enable_auto_scaling = true
    max_count          = 5
    min_count          = 2
    max_pods           = 110
    orchestrator_version = var.kubernetes_version
    os_disk_type = "Ephemeral"
    kubelet_disk_type = "OS"
    enable_node_public_ip = false
    node_labels = {
      "mode" = "System"
    }
  }

  identity {
    type = "SystemAssigned"
  }

  network_profile {
    network_plugin = "azure"
    network_policy = "calico"
    load_balancer_sku = "standard"
    outbound_type = "managedNATGateway"
  }

  azure_active_directory_role_based_access_control {
    managed = true
    admin_group_object_ids = [var.admin_group_id]
  }
}

# Configure the AWS Provider
provider "aws" {
  region = var.region
}

# Define variables
variable "region" {
  type        = string
  description = "AWS Region"
}

variable "asg_name" {
  type        = string
  description = "Auto Scaling Group Name"
}

variable "asg_instance_type" {
  type        = string
  description = "Instance Type for Auto Scaling Group"
}

variable "asg_ami" {
  type        = string
  description = "AMI ID for Auto Scaling Group"
}

variable "asg_key_name" {
  type        = string
  description = "Key Name for Auto Scaling Group"
}

variable "asg_public_ip" {
  type        = bool
  description = "Associate Public IP with Auto Scaling Group"
}

variable "security_group_id" {
  type        = string
  description = "Security Group ID for Auto Scaling Group"
}

variable "user_data" {
  type        = string
  description = "User Data for Auto Scaling Group"
}

variable "min_size" {
  type        = number
  description = "Minimum Size for Auto Scaling Group"
}

variable "max_size" {
  type        = number
  description = "Maximum Size for Auto Scaling Group"
}

variable "desired_capacity" {
  type        = number
  description = "Desired Capacity for Auto Scaling Group"
}

variable "public_subnet_ids" {
  type        = list(string)
  description = "Public Subnet IDs for Auto Scaling Group"
}

variable "target_group_arns" {
  type        = list(string)
  description = "Target Group ARNs for Auto Scaling Group"
}

variable "launch_template_version" {
  type        = string
  description = "Launch Template Version for Auto Scaling Group"
}

# Create a launch template
resource "aws_launch_template" "launch_template" {
  instance_type = var.asg_instance_type
  image_id      = var.asg_ami
  key_name      = var.asg_key_name
  network_interfaces {
    associate_public_ip_address = var.asg_public_ip
    security_groups             = [var.security_group_id]
  }
  user_data = var.user_data == null ? null : base64encode(file(var.user_data))
}

# Create an Auto Scaling Group
resource "aws_autoscaling_group" "asg" {
  name                = var.asg_name
  target_group_arns   = var.target_group_arns
  min_size            = var.min_size
  max_size            = var.max_size
  desired_capacity    = var.desired_capacity
  vpc_zone_identifier = var.public_subnet_ids
  launch_template {
    id      = aws_launch_template.launch_template.id
    version = var.launch_template_version
  }
}

# Create scaling policies
resource "aws_autoscaling_policy" "scale_up" {
  name                   = "${var.asg_name}-scale-up"
  policy_type           = "SimpleScaling"
  autoscaling_group_name = aws_autoscaling_group.asg.name
  scaling_adjustment     = 1
  adjustment_type        = "ChangeInCapacity"
  cooldown               = 60
}

resource "aws_autoscaling_policy" "scale_down" {
  name                   = "${var.asg_name}-scale-down"
  policy_type           = "SimpleScaling"
  autoscaling_group_name = aws_autoscaling_group.asg.name
  scaling_adjustment     = -1
  adjustment_type        = "ChangeInCapacity"
  cooldown               = 60
}

# Create CloudWatch alarms for scaling policies
resource "aws_cloudwatch_metric_alarm" "scale_up_alarm" {
  alarm_name                = "${var.asg_name}-scale-up-alarm"
  comparison_operator       = "GreaterThanThreshold"
  evaluation_periods        = 1
  metric_name               = "CPUUtilization"
  namespace                 = "AWS/EC2"
  period                    = 300
  statistic                 = "Average"
  threshold                 = 50
  alarm_description         = "Scale up alarm"
  actions_enabled           = true
  alarm_actions             = [aws_autoscaling_policy.scale_up.arn]
  insufficient_data_actions = []
  ok_actions                = []
}

resource "aws_cloudwatch_metric_alarm" "scale_down_alarm" {
  alarm_name                = "${var.asg_name}-scale-down-alarm"
  comparison_operator       = "LessThanThreshold"
  evaluation_periods        = 1
  metric_name               = "CPUUtilization"
  namespace                 = "AWS/EC2"
  period                    = 300
  statistic                 = "Average"
  threshold                 = 20
  alarm_description         = "Scale down alarm"
  actions_enabled           = true
  alarm_actions             = [aws_autoscaling_policy.scale_down.arn]
  insufficient_data_actions = []
  ok_actions                = []
}

variable "queue_name" {
  type        = string
  description = "The name of the SQS queue"
}

variable "dead_letter_queue_name" {
  type        = string
  description = "The name of the dead-letter SQS queue"
}

variable "max_receive_count" {
  type        = number
  description = "The maximum number of times a message can be received before being moved to the dead-letter queue"
  default     = 5
}

variable "access_policy_identifiers" {
  type        = list(string)
  description = "The identifiers of the principals that are allowed to access the SQS queue"
  default     = ["*"]
}

resource "aws_sqs_queue" "queue" {
  name                        = var.queue_name
  delay_seconds               = 300
  message_retention_period    = 86400
  receive_wait_time_seconds   = 10
  visibility_timeout_seconds  = 300
}

resource "aws_sqs_queue" "dead_letter_queue" {
  name                        = var.dead_letter_queue_name
  delay_seconds               = 300
  message_retention_period    = 86400
  receive_wait_time_seconds   = 10
  visibility_timeout_seconds  = 300
}

resource "aws_sqs_queue_policy" "queue_policy" {
  queue_url = aws_sqs_queue.queue.id
  policy    = data.aws_iam_policy_document.queue_policy_document.json
}

data "aws_iam_policy_document" "queue_policy_document" {
  statement {
    actions = [
      "SQS:SendMessage",
    ]

    condition {
      test     = "ArnEquals"
      variable = "AWS:SourceARN"

      values = [
        aws_sqs_queue.queue.arn,
      ]
    }

    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = var.access_policy_identifiers
    }

    resources = [
      aws_sqs_queue.queue.arn,
    ]
  }

  statement {
    actions = [
      "SQS:ReceiveMessage",
      "SQS:DeleteMessage",
      "SQS:GetQueueAttributes",
    ]

    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = var.access_policy_identifiers
    }

    resources = [
      aws_sqs_queue.queue.arn,
    ]
  }
}

resource "aws_sqs_queue_redrive_policy" "queue_redrive_policy" {
  queue_url = aws_sqs_queue.queue.id

  redrive_policy = jsonencode({
    deadLetterTargetArn = aws_sqs_queue.dead_letter_queue.arn
    maxReceiveCount     = var.max_receive_count
  })
}

#########################################################################################
# This configuration creates a Compute Engine instance in GCP
# with a network interface and firewall tag.
#########################################################################################

###########################
# VARIABLES
############################

# Google Cloud variables
variable "project_id" {}
variable "region" {
  default = "us-central1"
}
variable "zone" {
  default = "us-central1-a"
}

# Compute Engine instance variables
variable "instance_name" {}
variable "machine_type" {
  default = "f1-micro"
}
variable "image" {
  default = "debian-cloud/debian-9"
}

# Network variables
variable "network_name" {}
variable "subnet_name" {}
variable "subnet_ip" {
  default = "10.10.10.0/24"
}

# Firewall variables
variable "firewall_name" {}
variable "firewall_tag" {}

############################
# PROVIDERS
############################

provider "google" {
  version = "~> 4.0"
  project = var.project_id
  region  = var.region
}

############################
# RESOURCES
############################

# Create the network
resource "google_compute_network" "network" {
  name                    = var.network_name
  auto_create_subnetworks = false
}

# Create the subnet
resource "google_compute_subnetwork" "subnet" {
  name          = var.subnet_name
  ip_cidr_range = var.subnet_ip
  network       = google_compute_network.network.id
  region        = var.region
}

# Create the firewall rule
resource "google_compute_firewall" "firewall" {
  name    = var.firewall_name
  network = google_compute_network.network.id

  allow {
    protocol = "tcp"
    ports    = ["22"]
  }

  target_tags = [var.firewall_tag]
}

# Create the Compute Engine instance
resource "google_compute_instance" "instance" {
  name         = var.instance_name
  machine_type = var.machine_type
  zone         = var.zone

  boot_disk {
    initialize_params {
      image = var.image
    }
  }

  network_interface {
    network = google_compute_network.network.id
    subnetwork = google_compute_subnetwork.subnet.id
    access_config {
    }
  }

  tags = [var.firewall_tag]
}

variable "prefix" {
  type        = string
  description = "Prefix for resource names"
}

variable "resource_group_name" {
  type        = string
  description = "Name of the resource group"
}

variable "location" {
  type        = string
  description = "Location of the resources"
}

variable "subnet_id" {
  type        = string
  description = "ID of the subnet for the Application Gateway"
}

variable "public_ip_address_id" {
  type        = string
  description = "ID of the public IP address for the Application Gateway"
}

variable "waf_policy_id" {
  type        = string
  description = "ID of the WAF policy"
}

variable "backend_address_pool_addresses" {
  type        = list(string)
  description = "List of IP addresses or FQDNs for the backend pool"
}

locals {
  frontend_port_name             = "${var.prefix}-app-gateway-frontend-port"
  frontend_ip_configuration_name = "${var.prefix}-app-gateway-frontend-ip"
  backend_address_pool_name      = "${var.prefix}-app-gateway-backend-pool"
  backend_http_setting_name      = "${var.prefix}-app-gateway-backend-http-setting"
  listener_name                  = "${var.prefix}-app-gateway-listener"
  request_routing_rule_name      = "${var.prefix}-app-gateway-request-routing-rule"
}

resource "azurerm_public_ip" "app_gateway" {
  name                = "${var.prefix}-app-gateway-public-ip"
  resource_group_name = var.resource_group_name
  location            = var.location
  allocation_method   = "Dynamic"
}

resource "azurerm_application_gateway" "main" {
  name                = "${var.prefix}-app-gateway"
  resource_group_name = var.resource_group_name
  location            = var.location

  sku {
    name     = "WAF_v2"
    tier     = "WAF_v2"
    capacity = 2
  }

  gateway_ip_configuration {
    name      = "my-gateway-ip-configuration"
    subnet_id = var.subnet_id
  }

  frontend_port {
    name = local.frontend_port_name
    port = 80
  }

  frontend_ip_configuration {
    name                 = local.frontend_ip_configuration_name
    public_ip_address_id = azurerm_public_ip.app_gateway.id
  }

  backend_address_pool {
    name = local.backend_address_pool_name
  }

  backend_http_settings {
    name                  = local.backend_http_setting_name
    cookie_based_affinity = "Disabled"
    path                  = "/path1/"
    port                  = 80
    protocol              = "Http"
    request_timeout       = 60
  }

  http_listener {
    name                           = local.listener_name
    frontend_ip_configuration_name = local.frontend_ip_configuration_name
    frontend_port_name             = local.frontend_port_name
    protocol                       = "Http"
  }

  request_routing_rule {
    name                       = local.request_routing_rule_name
    rule_type                  = "Basic"
    http_listener_name         = local.listener_name
    backend_address_pool_name  = local.backend_address_pool_name
    backend_http_settings_name = local.backend_http_setting_name
  }

  web_application_firewall_configuration {
    enabled                  = true
    firewall_mode            = "Detection"
    rule_set_version         = "3.2"
    file_upload_limit_mb     = 100
    request_body_limit_kb    = 128
    max_file_upload_limit_mb = 500
  }
}

resource "azurerm_application_gateway_backend_address_pool_address" "main" {
  count                   = length(var.backend_address_pool_addresses)
  name                    = "${local.backend_address_pool_name}-${count.index}"
  application_gateway_name = azurerm_application_gateway.main.name
  resource_group_name     = var.resource_group_name
  ip_address              = var.backend_address_pool_addresses[count.index]
}

# Configure the AWS Provider
provider "aws" {
  region = var.aws_region
}

# Configure the Azure Provider
provider "azurerm" {
  features {}
}

# Configure the Google Cloud Provider
provider "google" {
  project = var.gcp_project
  region  = var.gcp_region
}

# AWS Route 53 DNS Zone
data "aws_route53_zone" "aws_dns" {
  name = var.aws_dns_name
}

# Create record in hosted zone for ACM Certificate Domain verification on AWS
resource "aws_route53_record" "aws_cert_validation" {
  for_each = {
    for val in aws_acm_certificate.aws_cert.domain_validation_options : val.domain_name => {
      name   = val.resource_record_name
      record = val.resource_record_value
      type   = val.resource_record_type
    }
  }
  name    = each.value.name
  records = [each.value.record]
  ttl     = 60
  type    = each.value.type
  zone_id = data.aws_route53_zone.aws_dns.zone_id
}

# Create Alias record towards ALB from Route53 on AWS
resource "aws_route53_record" "aws_jenkins" {
  zone_id  = data.aws_route53_zone.aws_dns.zone_id
  name     = join(".", ["jenkins", data.aws_route53_zone.aws_dns.name])
  type     = "A"
  alias {
    name                   = aws_lb.aws_alb.dns_name
    zone_id                = aws_lb.aws_alb.zone_id
    evaluate_target_health = true
  }
}

# Azure DNS Zone
resource "azurerm_private_dns_zone" "azure_dns" {
  name                = var.azure_dns_name
  resource_group_name = var.azure_rg_name
}

# Linking of DNS zones to Virtual Network on Azure
resource "azurerm_private_dns_zone_virtual_network_link" "azure_dns_link" {
  name                  = "${var.prefix}_link_azure_dns"
  resource_group_name   = var.azure_rg_name
  private_dns_zone_name = azurerm_private_dns_zone.azure_dns.name
  virtual_network_id    = var.azure_vnet_id
}

# Google Cloud DNS Zone
resource "google_dns_managed_zone" "gcp_dns" {
  name        = var.gcp_dns_name
  dns_name    = var.gcp_dns_zone
  description = "GCP DNS zone"
}

# Create DNS record on GCP
resource "google_dns_record_set" "gcp_dns_record" {
  name         = google_dns_managed_zone.gcp_dns.dns_name
  type         = "A"
  ttl          = 300
  managed_zone = google_dns_managed_zone.gcp_dns.name
  rrdatas      = [google_compute_address.gcp_address.address]
}

# Create a static IP address on GCP
resource "google_compute_address" "gcp_address" {
  name = "gcp-static-ip"
}

# Create a global forwarding rule on GCP
resource "google_compute_global_forwarding_rule" "gcp_forwarding_rule" {
  name       = "gcp-forwarding-rule"
  target     = google_compute_target_http_proxy.gcp_target_http_proxy.self_link
  port_range = "80"
}

# Create a target HTTP proxy on GCP
resource "google_compute_target_http_proxy" "gcp_target_http_proxy" {
  name    = "gcp-target-http-proxy"
  url_map = google_compute_url_map.gcp_url_map.self_link
}

# Create a URL map on GCP
resource "google_compute_url_map" "gcp_url_map" {
  name            = "gcp-url-map"
  default_service = google_compute_backend_service.gcp_backend_service.self_link
}

# Create a backend service on GCP
resource "google_compute_backend_service" "gcp_backend_service" {
  name        = "gcp-backend-service"
  protocol    = "HTTP"
  timeout_sec = 10
  health_checks = [
    google_compute_health_check.gcp_health_check.self_link
  ]
}

# Create a health check on GCP
resource "google_compute_health_check" "gcp_health_check" {
  name                = "gcp-health-check"
  check_interval_sec  = 1
  timeout_sec         = 1
  healthy_threshold   = 1
  unhealthy_threshold = 10
  http_health_check {
    port = 80
  }
}

provider "aws" {
  region = var.region
}

resource "aws_vpc" "main" {
