resource "azurerm_application_gateway" "example" {
  name                = var.application_gateway_name
  location            = azurerm_resource_group.example.location
  resource_group_name = azurerm_resource_group.example.name

  sku {
    name = "Standard_Small"
    tier = "Standard"
  }

  gateway_ip_configuration {
    name      = "example-gateway-ip-configuration"
    subnet_id = azurerm_subnet.example.id
  }

  frontend_port {
    name = var.frontend_port_name
    port = 80
  }

  frontend_ip_configuration {
    name                 = "example-frontend-ip-configuration"
    public_ip_address_id = azurerm_public_ip.example.id
  }

  backend_address_pool {
    name = var.backend_address_pool_name
  }

  backend_http_settings {
    name                  = var.backend_http_settings_name
    cookie_based_affinity = "Disabled"
    port                  = 80
    protocol              = "Http"
    request_timeout       = 60
  }

  http_listener {
    name                           = var.http_listener_name
    frontend_ip_configuration_name = "example-frontend-ip-configuration"
    frontend_port_name             = var.frontend_port_name
    protocol                       = "Http"
  }

  request_routing_rule {
    name                       = var.request_routing_rule_name
    rule_type                  = "Basic"
    http_listener_name         = var.http_listener_name
    backend_address_pool_name  = var.backend_address_pool_name
    backend_http_settings_name = var.backend_http_settings_name
  }
}

#########################################################################################
# This configuration creates a Dataflow job, staging bucket, and service account in GCP
#########################################################################################

###########################
# VARIABLES
############################

variable "project_id" {}
variable "region" {
  default = "us-central1"
}
variable "bucket_name" {}
variable "service_account_name" {}
variable "dataflow_job_name" {}
variable "dataflow_job_file" {}
variable "dataflow_job_class" {}
variable "dataflow_job_args" {
  type = list(string)
  default = []
}

############################
# PROVIDERS
############################

provider "google" {
  version = "~> 4.0"
  project = var.project_id
  region  = var.region
}

############################
# RESOURCES
############################

resource "google_storage_bucket" "staging_bucket" {
  name     = var.bucket_name
  location = var.region
  storage_class = "REGIONAL"
}

resource "google_service_account" "dataflow_service_account" {
  account_id   = var.service_account_name
  display_name = "Dataflow Service Account"
}

resource "google_project_iam_member" "dataflow_service_account_role" {
  project = var.project_id
  role    = "roles/dataflow.worker"
  member  = "serviceAccount:${google_service_account.dataflow_service_account.email}"
}

resource "google_dataflow_flex_template_run" "dataflow_job" {
  provider                = google
  project                 = var.project_id
  region                  = var.region
  template_gcs_path       = "${google_storage_bucket.staging_bucket.name}/${var.dataflow_job_file}"
  parameters = {
    "job-name" = var.dataflow_job_name
  }
  service_account_email = google_service_account.dataflow_service_account.email
  container_spec_gcs_path = "${google_storage_bucket.staging_bucket.name}/${var.dataflow_job_file}"
}

output "staging_bucket_name" {
  value = google_storage_bucket.staging_bucket.name
}

output "dataflow_service_account_email" {
  value = google_service_account.dataflow_service_account.email
}

output "dataflow_job_id" {
  value = google_dataflow_flex_template_run.dataflow_job.id
}

variable "cluster_name" {
  type        = string
  description = "The name of the EKS cluster"
}

variable "subnet_ids" {
  type        = list(string)
  description = "The IDs of the subnets to use for the node group"
}

variable "node_instance_type" {
  type        = string
  description = "The instance type to use for the node group"
}

variable "desired_capacity" {
  type        = number
  description = "The desired capacity for the node group"
}

variable "max_size" {
  type        = number
  description = "The maximum size for the node group"
}

variable "min_size" {
  type        = number
  description = "The minimum size for the node group"
}

variable "key_name" {
  type        = string
  description = "The name of the SSH key to use for the node group"
}

variable "k8s_version" {
  type        = string
  description = "The version of Kubernetes to use for the node group"
}

provider "aws" {
  region = "eu-west-1"
}

provider "kubernetes" {
  host                   = aws_eks_cluster.eks.cluster_endpoint
  cluster_ca_certificate = base64decode(aws_eks_cluster.eks.certificate_authority[0].data)

  exec {
    api_version = "client.authentication.k8s.io/v1beta1"
    command     = "aws"
    args = [
      "eks",
      "get-token",
      "--cluster-name",
      aws_eks_cluster.eks.name,
    ]
  }
}

data "aws_eks_cluster" "eks" {
  name = var.cluster_name
}

data "aws_subnets" "subnets" {
  filter {
    name   = "subnet-id"
    values = var.subnet_ids
  }
}

resource "aws_iam_role" "node" {
  name = "${var.cluster_name}-eks-node-role"

  assume_role_policy = <<POLICY
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Effect": "Allow",
      "Principal": {
        "Service": "ec2.amazonaws.com"
      },
      "Action": "sts:AssumeRole"
    }
  ]
}
POLICY
}

resource "aws_iam_role_policy_attachment" "node-AmazonEKSWorkerNodePolicy" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSWorkerNodePolicy"
  role       = aws_iam_role.node.name
}

resource "aws_iam_role_policy_attachment" "node-AmazonEKS_CNI_Policy" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKS_CNI_Policy"
  role       = aws_iam_role.node.name
}

resource "aws_iam_role_policy_attachment" "node-AmazonEC2ContainerRegistryReadOnly" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEC2ContainerRegistryReadOnly"
  role       = aws_iam_role.node.name
}

resource "aws_iam_instance_profile" "node" {
  name = "${var.cluster_name}-eks-node-instance-profile"
  role = aws_iam_role.node.name
}

resource "aws_eks_node_group" "node" {
  cluster_name    = var.cluster_name
  node_group_name = "${var.cluster_name}-node-group"
  node_role_arn   = aws_iam_role.node.arn
  subnet_ids      = var.subnet_ids

  instance_types = [var.node_instance_type]

  scaling_config {
    desired_size = var.desired_capacity
    max_size     = var.max_size
    min_size     = var.min_size
  }

  depends_on = [
    aws_iam_role_policy_attachment.node-AmazonEKSWorkerNodePolicy,
    aws_iam_role_policy_attachment.node-AmazonEKS_CNI_Policy,
    aws_iam_role_policy_attachment.node-AmazonEC2ContainerRegistryReadOnly,
  ]
}

provider "google" {
  project     = var.project_id
  region      = var.region
}

resource "random_id" "network_id" {
  byte_length = 8
}

module "vpc" {
  source  = "terraform-google-modules/network/google"
  version = "~> 2.5.0"

  project_id   = var.project_id
  network_name = "my-vpc-${random_id.network_id.hex}"
  routing_mode = "GLOBAL"

  subnets = [
    {
      subnet_name           = "subnet-01"
      subnet_ip             = "10.10.10.0/24"
      subnet_region         = var.region
    },
    {
      subnet_name           = "subnet-02"
      subnet_ip             = "10.10.20.0/24"
      subnet_region         = var.region
    }
  ]
}

resource "google_compute_firewall" "ingress-rules" {
  project     = var.project_id
  name        = "tf-firewall"
  network     = module.vpc.network_name
  description = "Creates firewall rule targeting tagged instances"

  direction   = "INGRESS"

  allow {
    protocol  = "tcp"
    ports     = ["80", "22"]
  }

  source_ranges = ["0.0.0.0/0"]
}

resource "google_compute_firewall" "egress-rules" {
  project     = var.project_id
  name        = "tf-egress-firewall"
  network     = module.vpc.network_name
  description = "Creates firewall rule targeting tagged instances"

  direction   = "EGRESS"

  allow {
    protocol  = "all"
  }

  destination_ranges = ["0.0.0.0/0"]
}

resource "google_compute_router" "router" {
  project = var.project_id
  region  = var.region
  name    = "my-router"
  network = module.vpc.network_name
}

resource "google_compute_router_nat" "nat" {
  project                            = var.project_id
  region                             = var.region
  router                             = google_compute_router.router.name
  nat_ip_allocate_option             = "AUTO_ONLY"
  source_subnetwork_ip_ranges_to_nat = "ALL_SUBNETWORKS_ALL_IP_RANGES"
}

