  default     = "my-gcp-project"
  description = "GCP project ID"
}

variable "gcp_region" {
  type        = string
  default     = "us-central1"
  description = "GCP region"
}

variable "azure_subscription_id" {
  type        = string
  default     = "my-azure-subscription-id"
  description = "Azure subscription ID"
}

variable "azure_resource_group_name" {
  type        = string
  default     = "my-azure-resource-group"
  description = "Azure resource group name"
}

variable "cluster_name" {
  type        = string
  default     = "my-kubernetes-cluster"
  description = "Kubernetes cluster name"
}

variable "cluster_version" {
  type        = string
  default     = "1.22"
  description = "Kubernetes cluster version"
}

# Define locals
locals {
  name            = "ex-${replace(basename(path.cwd), "_", "-")}"
  tags = {
    Example    = local.name
    GithubRepo = "terraform-aws-eks"
    GithubOrg  = "terraform-aws-modules"
  }
}

# Create EKS cluster
module "eks" {
  source = "../.."

  cluster_name                    = var.cluster_name
  cluster_version                 = var.cluster_version
  cluster_endpoint_private_access = true
  cluster_endpoint_public_access  = true

  cluster_addons = {
    kube-proxy = {}
    vpc-cni    = {}
  }

  cluster_encryption_config = [{
    provider_key_arn = aws_kms_key.eks.arn
    resources        = ["secrets"]
  }]

  vpc_id     = module.vpc.vpc_id
  subnet_ids = module.vpc.private_subnets
}

# Create AKS cluster
module "aks" {
  source = "../../aks"

  resource_group_name = var.azure_resource_group_name
  location            = var.azure_location
  cluster_name        = var.cluster_name
  kubernetes_version  = var.cluster_version

  network_profile = {
    network_plugin = "azure"
  }

  default_node_pool = {
    name       = "default"
    node_count = 3
    vm_size     = "Standard_DS2_v2"
  }
}

# Create GKE cluster
module "gke" {
  source = "../../gke"

  project_id = var.gcp_project
  location   = var.gcp_region
  cluster_id = var.cluster_name

  node_pool = {
    name       = "default"
    node_count = 3
    machine_type = "n1-standard-1"
  }
}

# Create VPC
module "vpc" {
  source = "../.."

  cidr = "10.0.0.0/16"

  azs             = ["us-west-2a", "us-west-2b", "us-west-2c"]
  private_subnets = ["10.0.1.0/24", "10.0.2.0/24", "10.0.3.0/24"]
  public_subnets  = ["10.0.4.0/24", "10.0.5.0/24", "10.0.6.0/24"]

  enable_nat_gateway = true
  enable_vpn_gateway = false

  tags = {
    "kubernetes.io/cluster/${var.cluster_name}" = "shared"
  }
}

# Create KMS key for EKS
resource "aws_kms_key" "eks" {
  description             = "EKS KMS key"
  deletion_window_in_days = 10
}

# Create Azure resource group
resource "azurerm_resource_group" "example" {
  name     = var.azure_resource_group_name
  location = var.azure_location
}

# Create GCP project
resource "google_project" "example" {
  project_id = var.gcp_project
}

terraform {
  required_providers {
    azurerm = {
      version = "~>3.47.0"
      source  = "hashicorp/azurerm"
    }
    azurecaf = {
      source  = "aztfmod/azurecaf"
      version = "~>1.2.24"
    }
  }
}

variable "resource_token" {
  type = string
}

variable "location" {
  type = string
}

variable "rg_name" {
  type = string
}

variable "tags" {
  type = map(string)
}

resource "azurecaf_name" "workspace_name" {
  name          = var.resource_token
  resource_type = "azurerm_log_analytics_workspace"
  random_length = 0
  clean_input   = true
}

resource "azurerm_log_analytics_workspace" "workspace" {
  name                = azurecaf_name.workspace_name.result
  location            = var.location
  resource_group_name = var.rg_name
  sku                 = "PerGB2018"
  retention_in_days   = 30
  tags                = var.tags
}

resource "azurerm_monitor_diagnostic_setting" "example" {
  name                       = "example"
  target_resource_id         = azurerm_log_analytics_workspace.workspace.id
  log_analytics_workspace_id = azurerm_log_analytics_workspace.workspace.id

  log {
    category = "Audit"
    enabled  = true

    retention_policy {
      enabled = true
      days    = 30
    }
  }

  metric {
    category = "AllMetrics"
    enabled  = true

    retention_policy {
      enabled = true
      days    = 30
    }
  }
}

# Configure the AWS Provider
provider "aws" {
  region = var.aws_region
}

# Configure the Azure Provider
provider "azurerm" {
  features {}
}

# Configure the Google Cloud Provider
provider "google" {
  project = var.google_project
  region  = var.google_region
}

# Create AWS S3 Bucket
resource "aws_s3_bucket" "aws_object_storage" {
  bucket = var.aws_bucket_name

  lifecycle {
    prevent_destroy = true
  }

  tags = {
    Name = var.aws_bucket_name
  }
}

# Create Azure Storage Account
resource "azurerm_storage_account" "azure_object_storage" {
  name                     = var.azure_storage_account_name
  resource_group_name      = var.azure_resource_group_name
  location                 = var.azure_location
  account_tier             = "Standard"
  account_replication_type = "LRS"

  tags = {
    environment = var.environment
  }
}

# Create GCP Cloud Storage Bucket
resource "google_storage_bucket" "gcp_object_storage" {
  name          = var.gcp_bucket_name
  location      = var.gcp_location
  project       = var.google_project
  storage_class = "STANDARD"
}

# Create Azure Storage Container
resource "azurerm_storage_container" "azure_container" {
  name                  = var.azure_container_name
  storage_account_name  = azurerm_storage_account.azure_object_storage.name
  container_access_type = "private"
}

# Create GCP Cloud Storage Bucket Public Access Block
resource "google_storage_bucket_iam_binding" "gcp_bucket_iam_binding" {
  bucket = google_storage_bucket.gcp_object_storage.name
  role   = "roles/storage.objectViewer"
  members = [
    "allUsers",
  ]
}

# Create AWS S3 Bucket Public Access Block
resource "aws_s3_bucket_public_access_block" "aws_public_access" {
  bucket = aws_s3_bucket.aws_object_storage.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

