terraform {
  required_version = ">= 0.12.7"
}

# ---------------------------------------------------------------------------------------------------------------------
# Configure the Google Cloud Provider
# ---------------------------------------------------------------------------------------------------------------------
provider "google" {
  project = var.project
  region  = var.region
}

# ---------------------------------------------------------------------------------------------------------------------
# Configure the Google Cloud Beta Provider
# ---------------------------------------------------------------------------------------------------------------------
provider "google-beta" {
  project = var.project
  region  = var.region
}

# ---------------------------------------------------------------------------------------------------------------------
# Create a GKE node pool
# ---------------------------------------------------------------------------------------------------------------------
resource "google_container_node_pool" "node_pool" {
  provider = google-beta
  name       = var.node_pool_name
  location   = var.location
  cluster    = var.cluster_name
  node_count = var.node_count

  node_config {
    preemptible  = var.preemptible
    machine_type = var.machine_type
    disk_size_gb = var.disk_size_gb
    oauth_scopes = var.oauth_scopes
  }

  autoscaling {
    min_node_count = var.min_node_count
    max_node_count = var.max_node_count
  }

  management {
    auto_repair  = var.auto_repair
    auto_upgrade = var.auto_upgrade
  }

  upgrade_settings {
    max_surge       = var.max_surge
    max_unavailable = var.max_unavailable
  }
}

variable "project" {
  type        = string
  description = "The ID of the project to create the cluster in"
}

variable "location" {
  type        = string
  description = "The location to create the cluster in"
}

variable "node_pool_name" {
  type        = string
  description = "The name of the node pool"
}

variable "cluster_name" {
  type        = string
  description = "The name of the cluster to create the node pool in"
}

variable "node_count" {
  type        = number
  description = "The number of nodes to create in the node pool"
}

variable "preemptible" {
  type        = bool
  description = "Whether the nodes in the node pool are preemptible"
}

variable "machine_type" {
  type        = string
  description = "The machine type to use for the nodes in the node pool"
}

variable "disk_size_gb" {
  type        = number
  description = "The size of the disk to use for the nodes in the node pool"
}

variable "oauth_scopes" {
  type        = list(string)
  description = "The OAuth scopes to use for the nodes in the node pool"
}

variable "min_node_count" {
  type        = number
  description = "The minimum number of nodes to create in the node pool"
}

variable "max_node_count" {
  type        = number
  description = "The maximum number of nodes to create in the node pool"
}

variable "auto_repair" {
  type        = bool
  description = "Whether to automatically repair the nodes in the node pool"
}

variable "auto_upgrade" {
  type        = bool
  description = "Whether to automatically upgrade the nodes in the node pool"
}

variable "max_surge" {
  type        = number
  description = "The maximum number of nodes to surge during an upgrade"
}

variable "max_unavailable" {
  type        = number
  description = "The maximum number of nodes to make unavailable during an upgrade"
}

# Configure the AWS Provider
provider "aws" {
  region = var.aws_region
}

# Configure the Azure Provider
provider "azurerm" {
  features {}
}

# Configure the Google Cloud Provider
provider "google" {
  project = var.gcp_project
  region  = var.gcp_region
}

# AWS Route 53 DNS Zone
data "aws_route53_zone" "aws_dns" {
  name = var.aws_dns_name
}

# Create record in hosted zone for ACM Certificate Domain verification on AWS
resource "aws_route53_record" "aws_cert_validation" {
  for_each = {
    for val in aws_acm_certificate.aws_cert.domain_validation_options : val.domain_name => {
      name   = val.resource_record_name
      record = val.resource_record_value
      type   = val.resource_record_type
    }
  }
  name    = each.value.name
  records = [each.value.record]
  ttl     = 60
  type    = each.value.type
  zone_id = data.aws_route53_zone.aws_dns.zone_id
}

# Create Alias record towards ALB from Route53 on AWS
resource "aws_route53_record" "aws_jenkins" {
  zone_id  = data.aws_route53_zone.aws_dns.zone_id
  name     = join(".", ["jenkins", data.aws_route53_zone.aws_dns.name])
  type     = "A"
  alias {
    name                   = aws_lb.aws_alb.dns_name
    zone_id                = aws_lb.aws_alb.zone_id
    evaluate_target_health = true
  }
}

# Azure DNS Zone
resource "azurerm_private_dns_zone" "azure_dns" {
  name                = var.azure_dns_name
  resource_group_name = var.azure_rg_name
}

# Linking of DNS zones to Virtual Network on Azure
resource "azurerm_private_dns_zone_virtual_network_link" "azure_dns_link" {
  name                  = "${var.prefix}_link_azure"
  resource_group_name   = var.azure_rg_name
  private_dns_zone_name = azurerm_private_dns_zone.azure_dns.name
  virtual_network_id    = var.azure_vnet_id
}

# GCP Cloud DNS Zone
resource "google_dns_managed_zone" "gcp_dns" {
  name        = var.gcp_dns_name
  dns_name    = var.gcp_dns_zone
  description = "GCP Cloud DNS Zone"
}

# Store state in a Cloud Storage bucket on GCP
terraform {
  backend "gcs" {
    bucket  = var.gcp_bucket
    prefix  = "terraform/state/dns"
    project = var.gcp_project
  }
}

