variable "project_id" {
  type        = string
  description = "The ID of the project to deploy to"
}

variable "location" {
  type        = string
  description = "The location to deploy to"
}

variable "service_name" {
  type        = string
  description = "The name of the Cloud Run service"
}

variable "image_url" {
  type        = string
  description = "The URL of the container image to deploy"
}

variable "traffic_percentages" {
  type        = map(number)
  description = "A map of traffic percentages for each revision"
}

variable "iam_members" {
  type        = list(string)
  description = "A list of IAM members to bind to the service"
}

locals {
  service_account_email = "service-${data.google_project.project.number}@gcp-sa-cloudbuild.iam.gserviceaccount.com"
}

data "google_project" "project" {
  project_id = var.project_id
}

resource "google_cloud_run_service" "default" {
  name     = var.service_name
  location = var.location

  template {
    spec {
      containers {
        image = var.image_url
      }
    }
  }

  traffic {
    percent         = var.traffic_percentages["latest"]
    latest_revision = true
  }

  dynamic "traffic" {
    for_each = var.traffic_percentages
    content {
      percent = traffic.value
      revision = google_cloud_run_revision.default[traffic.key].name
    }
  }
}

resource "google_cloud_run_revision" "default" {
  for_each = var.traffic_percentages
  service  = google_cloud_run_service.default.name

  template {
    spec {
      containers {
        image = var.image_url
      }
    }
  }
}

resource "google_cloud_run_service_iam_member" "default" {
  for_each = toset(var.iam_members)
  service  = google_cloud_run_service.default.name
  role     = "roles/run.invoker"
  member   = each.value
}

resource "google_cloud_run_service_iam_member" "service_account" {
  service  = google_cloud_run_service.default.name
  role     = "roles/run.invoker"
  member   = local.service_account_email
}

variable "queue_name" {
  type        = string
  description = "Name of the SQS queue"
}

variable "dead_letter_queue_name" {
  type        = string
  description = "Name of the dead-letter SQS queue"
}

variable "max_receive_count" {
  type        = number
  description = "Maximum number of times a message can be received before being moved to the dead-letter queue"
  default     = 5
}

variable "message_retention_seconds" {
  type        = number
  description = "Number of seconds to retain messages in the queue"
  default     = 86400
}

variable "visibility_timeout_seconds" {
  type        = number
  description = "Number of seconds to wait before receiving a message again"
  default     = 30
}

variable "delay_seconds" {
  type        = number
  description = "Number of seconds to delay before delivering a message"
  default     = 0
}

variable "policy_actions" {
  type        = list(string)
  description = "List of actions to allow in the SQS queue policy"
  default     = ["SQS:SendMessage", "SQS:ReceiveMessage", "SQS:DeleteMessage", "SQS:GetQueueAttributes"]
}

variable "policy_principals" {
  type        = list(string)
  description = "List of principals to allow in the SQS queue policy"
  default     = ["*"]
}

resource "aws_sqs_queue" "queue" {
  name                        = var.queue_name
  delay_seconds               = var.delay_seconds
  message_retention_period    = var.message_retention_seconds
  visibility_timeout_seconds  = var.visibility_timeout_seconds
  receive_wait_time_seconds   = 10
  redrive_policy              = jsonencode({
    deadLetterTargetArn = aws_sqs_queue.dead_letter_queue.arn
    maxReceiveCount     = var.max_receive_count
  })
}

resource "aws_sqs_queue" "dead_letter_queue" {
  name                        = var.dead_letter_queue_name
  delay_seconds               = var.delay_seconds
  message_retention_period    = var.message_retention_seconds
  visibility_timeout_seconds  = var.visibility_timeout_seconds
  receive_wait_time_seconds   = 10
}

data "aws_iam_policy_document" "sqs_policy" {
  statement {
    actions = var.policy_actions

    condition {
      test     = "ArnEquals"
      variable = "AWS:SourceARN"

      values = [
        aws_sqs_queue.queue.arn,
      ]
    }

    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = var.policy_principals
    }

    resources = [
      aws_sqs_queue.queue.arn,
    ]
  }
}

resource "aws_sqs_queue_policy" "sqs_policy" {
  queue_url = aws_sqs_queue.queue.id
  policy    = data.aws_iam_policy_document.sqs_policy.json
}

#########################################################################################
# This configuration creates a Compute Engine instance in GCP
# with a network interface and firewall tag.
#########################################################################################

###########################
# VARIABLES
############################

# Google Cloud variables
variable "project_id" {}
variable "region" {
  default = "us-central1"
}
variable "zone" {
  default = "us-central1-a"
}

# Compute Engine instance variables
variable "instance_name" {}
variable "machine_type" {
  default = "f1-micro"
}
variable "image" {
  default = "debian-cloud/debian-9"
}

# Network variables
variable "network_name" {}
variable "subnet_name" {}
variable "subnet_ip" {
  default = "10.10.10.0/24"
}

# Firewall variables
variable "firewall_name" {}
variable "firewall_tag" {}

############################
# PROVIDERS
############################

provider "google" {
  version = "~> 2.0"
  region  = var.region
  project = var.project_id
}

############################
# RESOURCES
############################

# Create the network
resource "google_compute_network" "network" {
  name                    = var.network_name
  auto_create_subnetworks = false
}

# Create the subnet
resource "google_compute_subnetwork" "subnet" {
  name          = var.subnet_name
  ip_cidr_range = var.subnet_ip
  network       = google_compute_network.network.self_link
  region        = var.region
}

# Create the firewall rule
resource "google_compute_firewall" "firewall" {
  name    = var.firewall_name
  network = google_compute_network.network.self_link

  allow {
    protocol = "tcp"
    ports    = ["22"]
  }

  target_tags = [var.firewall_tag]
}

# Create the Compute Engine instance
resource "google_compute_instance" "instance" {
  name         = var.instance_name
  machine_type = var.machine_type
  zone         = var.zone

  boot_disk {
    initialize_params {
      image = var.image
    }
  }

  network_interface {
    network = google_compute_network.network.self_link
    subnetwork = google_compute_subnetwork.subnet.self_link
  }

  tags = [var.firewall_tag]
}

variable "resource_group_name_prefix" {
  type        = string
  default     = "myrg"
}

variable "resource_group_location" {
  type        = string
  default     = "West US"
}

variable "vm_name" {
  type        = string
  default     = "mylinuxvm"
}

variable "admin_username" {
  type        = string
  default     = "azureuser"
}

variable "ssh_public_key_path" {
  type        = string
  default     = "./ssh-keys/terraform-azure.pub"
}

variable "custom_data_path" {
  type        = string
  default     = "./app-scripts/app1-cloud-init.txt"
}

resource "random_pet" "rg_name" {
  prefix = var.resource_group_name_prefix
}

resource "azurerm_resource_group" "rg" {
  location = var.resource_group_location
  name     = random_pet.rg_name.id
}

resource "azurerm_virtual_network" "my_terraform_network" {
  name                = "myVnet"
  address_space       = ["10.0.128.0/24"]
  location            = azurerm_resource_group.rg.location
  resource_group_name = azurerm_resource_group.rg.name
}

resource "azurerm_subnet" "my_terraform_subnet" {
  name                 = "mySubnet"
  resource_group_name  = azurerm_resource_group.rg.name
  virtual_network_name = azurerm_virtual_network.my_terraform_network.name
  address_prefixes     = ["10.0.128.0/24"]
}

resource "azurerm_public_ip" "my_terraform_public_ip" {
  name                = "myPublicIP"
  location            = azurerm_resource_group.rg.location
  resource_group_name = azurerm_resource_group.rg.name
  allocation_method   = "Dynamic"
}

resource "azurerm_network_security_group" "my_terraform_nsg" {
  name                = "myNetworkSecurityGroup"
  location            = azurerm_resource_group.rg.location
  resource_group_name = azurerm_resource_group.rg.name

  security_rule {
    name                       = "SSH"
    priority                   = 1001
    direction                  = "Inbound"
    access                     = "Allow"
    protocol                   = "Tcp"
    source_port_range          = "*"
    destination_port_range     = "22"
    source_address_prefix      = "*"
    destination_address_prefix = "*"
  }
}

resource "azurerm_network_interface" "myvmnic" {
  name                = "myvmnic"
  location            = azurerm_resource_group.rg.location
  resource_group_name = azurerm_resource_group.rg.name

  ip_configuration {
    name                          = "myNicConfiguration"
    subnet_id                     = azurerm_subnet.my_terraform_subnet.id
    private_ip_address_allocation = "Dynamic"
    public_ip_address_id          = azurerm_public_ip.my_terraform_public_ip.id
  }
}

resource "azurerm_linux_virtual_machine" "mylinuxvm" {
  name                = var.vm_name
  computer_name       = var.vm_name
  resource_group_name = azurerm_resource_group.rg.name
  location            = azurerm_resource_group.rg.location
  size                = "Standard_DS1_v2"
  admin_username      = var.admin_username
  network_interface_ids = [ azurerm_network_interface.myvmnic.id ]
  admin_ssh_key {
    username   = var.admin_username
    public_key = file(var.ssh_public_key_path)
  }
  os_disk {
    name = "osdisk"
    caching              = "ReadWrite"
    storage_account_type = "Standard_LRS"
  }
  source_image_reference {
    publisher = "RedHat"
    offer     = "RHEL"
    sku       = "83-gen2"
    version   = "latest"
  }
  custom_data = filebase64(var.custom_data_path)
}

terraform {
  required_providers {
    azurerm = {
      source  = "hashicorp/azurerm"
      version = "=2.86.0"
    }
  }
}

